import type { NodeInput } from '@archa/schema';
import INDEX from '../data/index.json';

/*
 * Icon library (blueprint DESIGN_SYSTEM/05): lucide, Tabler, Phosphor, Heroicons and brand logos, generated by
 * scripts/gen-icon-sets.mjs. Each set is a lazily loaded JSON chunk; every icon is one path. Shared by the
 * canvas Assets panel and the agent `icon()` / `icons()` calls, so both insert the same vector.
 */

export type IconSetMeta = {
  id: string; label: string; family: string; style: string; licence: string; version: string;
  /** Square grid the paths are drawn on. */
  viewBox: number;
  /** stroke: outline drawn with `stroke` px on the grid · fill: solid shapes. */
  mode: 'stroke' | 'fill';
  stroke?: number;
  count: number;
};
/** Path data · [path, 'e'] when filled even-odd · logos: [path, brand hex, title]. */
export type IconEntry = string | [string, string] | [string, string, string];
export type IconSet = Omit<IconSetMeta, 'count'> & { icons: Record<string, IconEntry> };
export type Icon = { set: IconSetMeta; name: string; d: string; evenodd: boolean; brand?: string; title?: string };

export const ICON_SETS = INDEX as IconSetMeta[];
export const DEFAULT_SET = 'lucide';
/** Icons the person uploaded (stored per machine by the core host, not in this package). */
export const CUSTOM_SET = 'my';

const LOADERS: Record<string, () => Promise<{ default: unknown }>> = {
  lucide: () => import('../data/lucide.json'),
  tabler: () => import('../data/tabler.json'),
  'tabler-filled': () => import('../data/tabler-filled.json'),
  ph: () => import('../data/ph.json'),
  'ph-thin': () => import('../data/ph-thin.json'),
  'ph-light': () => import('../data/ph-light.json'),
  'ph-bold': () => import('../data/ph-bold.json'),
  'ph-fill': () => import('../data/ph-fill.json'),
  hero: () => import('../data/hero.json'),
  'hero-solid': () => import('../data/hero-solid.json'),
  'hero-mini': () => import('../data/hero-mini.json'),
  'hero-micro': () => import('../data/hero-micro.json'),
  logos: () => import('../data/logos.json'),
};

const pending = new Map<string, Promise<IconSet>>();
const loaded = new Map<string, IconSet>();

export function loadIconSet(id: string): Promise<IconSet> {
  const load = LOADERS[id];
  if (!load) return Promise.reject(new Error(`Unknown icon set "${id}"`));
  let p = pending.get(id);
  if (!p) {
    p = load().then((m) => { const set = m.default as IconSet; loaded.set(id, set); return set; });
    pending.set(id, p);
  }
  return p;
}

export const loadAllIconSets = () => Promise.all(ICON_SETS.map((s) => loadIconSet(s.id)));
/** A set already loaded, for synchronous callers (agent snippets). */
export const loadedIconSet = (id: string) => loaded.get(id);
export const iconSetMeta = (id: string) => ICON_SETS.find((s) => s.id === id);

/** "ArrowRight", "arrow_right", "arrow right" → "arrow-right". */
export const iconKey = (name: string) =>
  name.trim().replace(/Icon$/, '').replace(/([a-z0-9])([A-Z])/g, '$1-$2').replace(/[\s_]+/g, '-').toLowerCase();

const SET_ALIASES: Record<string, string> = {
  phosphor: 'ph', 'phosphor-fill': 'ph-fill', 'phosphor-bold': 'ph-bold', 'phosphor-light': 'ph-light', 'phosphor-thin': 'ph-thin',
  heroicons: 'hero', heroicon: 'hero', 'hero-outline': 'hero', 'heroicons-solid': 'hero-solid',
  'tabler-outline': 'tabler', 'tabler-fill': 'tabler-filled',
  logo: 'logos', brand: 'logos', brands: 'logos', si: 'logos', 'simple-icons': 'logos',
  mine: CUSTOM_SET, custom: CUSTOM_SET, 'my-icons': CUSTOM_SET,
};

/** "tabler:home" → { set: 'tabler', name: 'home' }; no prefix = lucide. */
export function parseIconRef(ref: string): { set: string; name: string } {
  const m = /^([a-z-]+):(.+)$/i.exec(ref.trim());
  if (!m) return { set: DEFAULT_SET, name: iconKey(ref) };
  const s = m[1]!.toLowerCase();
  const set = SET_ALIASES[s] ?? s;
  // Logo slugs are lower-case without separators ("github", "googlechrome").
  return { set, name: set === 'logos' ? m[2]!.toLowerCase().replace(/[\s_.-]+/g, '') : set === CUSTOM_SET ? m[2]!.trim() : iconKey(m[2]!) };
}

export const iconRef = (set: string, name: string) => (set === DEFAULT_SET ? name : `${set}:${name}`);

/** An icon of a loaded set, or null. */
export function getIcon(set: IconSet | undefined, name: string): Icon | null {
  const e = set?.icons[name];
  const meta = set && iconSetMeta(set.id);
  if (!e || !meta) return null;
  if (typeof e === 'string') return { set: meta, name, d: e, evenodd: false };
  if (e.length === 3) return { set: meta, name, d: e[0], evenodd: false, brand: e[1], title: e[2] };
  return { set: meta, name, d: e[0], evenodd: e[1] === 'e' };
}

/** Names ranked against a query (0 = exact … 4 = one word matches); titles let logos match their brand name. */
function rankNames(names: string[], query: string, titles?: (n: string) => string | undefined): Array<[string, number]> {
  const q = iconKey(query);
  const raw = query.trim().toLowerCase();
  const flat = q.replace(/-/g, '');
  const words = q.split('-').filter(Boolean);
  const score = (n: string) => {
    const t = titles?.(n)?.toLowerCase();
    if (n === q || n === flat || t === raw) return 0;
    if (n.startsWith(q) || n.startsWith(flat) || t?.startsWith(raw)) return 1;
    if (n.includes(q) || n.includes(flat)) return 2;
    if (words.every((w) => n.includes(w) || t?.includes(w))) return 3;
    return words.some((w) => w.length > 2 && (n.includes(w) || t?.includes(w))) ? 4 : 9;
  };
  const hits = names.map((n) => [n, score(n)] as [string, number]).filter(([, sc]) => sc < 9);
  if (hits.length) return hits.sort((a, b) => a[1] - b[1] || a[0].length - b[0].length);
  // Typos ("serch"): closest names by edit distance, ranked after every real match.
  return names.map((n) => [n, distance(n, q)] as [string, number]).filter(([, d]) => d <= 2).sort((a, b) => a[1] - b[1]).map(([n, d]) => [n, 5 + d]);
}

/** Names that best match a query: exact, prefix, substring, all words; typos fall back to edit distance. */
export function searchNames(names: string[], query: string, limit = 24, titles?: (n: string) => string | undefined): string[] {
  if (!iconKey(query)) return names.slice(0, limit);
  return rankNames(names, query, titles).slice(0, limit).map(([n]) => n);
}

const logoTitle = (set: IconSet) => (set.id === 'logos' ? (n: string) => { const e = set.icons[n]; return Array.isArray(e) && e.length === 3 ? e[2] : undefined; } : undefined);

/** Search one loaded set; logos also match their brand title. */
export function searchIconSet(set: IconSet, query: string, limit = 24): string[] {
  return searchNames(Object.keys(set.icons), query, limit, logoTitle(set));
}

/** Search every loaded set (or the listed ones), best matches first across sets; results are refs such as "tabler:home". */
export function searchIcons(query: string, opts: { sets?: string[]; limit?: number } = {}): string[] {
  const limit = opts.limit ?? 30;
  const ids = opts.sets?.length ? opts.sets.map((s) => SET_ALIASES[s] ?? s) : ICON_SETS.map((s) => s.id);
  const all: Array<[string, number, number]> = [];
  ids.forEach((id, order) => {
    const set = loaded.get(id);
    if (set) for (const [n, sc] of rankNames(Object.keys(set.icons), query, logoTitle(set)).slice(0, limit)) all.push([iconRef(id, n), sc, order]);
  });
  return all.sort((a, b) => a[1] - b[1] || a[2] - b[2] || a[0].length - b[0].length).slice(0, limit).map(([r]) => r);
}

function distance(a: string, b: string): number {
  if (Math.abs(a.length - b.length) > 2) return 9;
  let prev = Array.from({ length: b.length + 1 }, (_, i) => i);
  for (let i = 1; i <= a.length; i++) {
    const cur = [i];
    for (let j = 1; j <= b.length; j++) cur[j] = Math.min(prev[j]! + 1, cur[j - 1]! + 1, prev[j - 1]! + (a[i - 1] === b[j - 1] ? 0 : 1));
    prev = cur;
  }
  return prev[b.length]!;
}

export type IconNodeOptions = {
  size?: number;
  /** Colour; logos default to their brand colour. */
  color?: string;
  /** Outline weight on the set's own grid (lucide/Tabler 2, Heroicons outline 1.5). */
  strokeWidth?: number;
  name?: string;
};

/** One vector node for an icon: stroked for outline sets, filled for solid sets and logos. */
export function iconNode(icon: Icon, opts: IconNodeOptions = {}): NodeInput {
  const { set } = icon;
  const size = Number(opts.size) > 0 ? Number(opts.size) : 24;
  const color = opts.color ?? icon.brand ?? '#18181b';
  const base = {
    type: 'path', name: opts.name ?? (icon.title ?? `Icon ${icon.name}`), d: icon.d,
    viewBox: { x: 0, y: 0, width: set.viewBox, height: set.viewBox }, width: size, height: size,
    fillRule: icon.evenodd ? 'evenodd' : 'nonzero', lineCap: 'round', lineJoin: 'round',
  };
  return (set.mode === 'stroke'
    ? { ...base, fills: [], strokes: [{ color, width: ((Number(opts.strokeWidth) || set.stroke || 2) * size) / set.viewBox, align: 'center' }] }
    : { ...base, fills: [color], strokes: [] }) as unknown as NodeInput;
}

/** SVG markup of an icon (previews, copy as SVG). */
export function iconSvg(icon: Icon, color = 'currentColor', size = 24): string {
  const { set } = icon;
  const paint = set.mode === 'stroke'
    ? `fill="none" stroke="${color}" stroke-width="${set.stroke ?? 2}" stroke-linecap="round" stroke-linejoin="round"`
    : `fill="${color}"${icon.evenodd ? ' fill-rule="evenodd"' : ''}`;
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="0 0 ${set.viewBox} ${set.viewBox}"><path d="${icon.d}" ${paint}/></svg>`;
}

/** Uploaded icon: a node tree with its natural size (from the SVG importer). */
export type CustomIcon = { name: string; width: number; height: number; node: NodeInput; addedAt: number; /** data: URL shown in the Assets grid. */ preview?: string };

/** A copy of a node tree scaled by k (boxes, strokes, radii, gaps, padding, font sizes). */
export function scaleInput(input: NodeInput, k: number): NodeInput {
  const n = { ...input } as Record<string, unknown>;
  for (const key of ['x', 'y', 'width', 'height', 'cornerRadius', 'gap', 'fontSize', 'letterSpacing']) if (typeof n[key] === 'number') n[key] = (n[key] as number) * k;
  if (n.padding && typeof n.padding === 'object') n.padding = Object.fromEntries(Object.entries(n.padding as Record<string, number>).map(([a, v]) => [a, v * k]));
  if (Array.isArray(n.strokes)) n.strokes = (n.strokes as unknown[]).map((s) => (s && typeof s === 'object' && typeof (s as { width?: unknown }).width === 'number' ? { ...s, width: (s as { width: number }).width * k } : s));
  if (Array.isArray(n.children)) n.children = (n.children as NodeInput[]).map((c) => scaleInput(c, k));
  return n as NodeInput;
}

/** A copy of a node tree with every fill and stroke colour replaced (one-colour icons). */
export function recolorInput(input: NodeInput, color: string): NodeInput {
  const n = { ...input } as Record<string, unknown>;
  const paint = (p: unknown) => (typeof p === 'string' ? color : p && typeof p === 'object' ? { ...p, color } : p);
  if (Array.isArray(n.fills)) n.fills = (n.fills as unknown[]).map(paint);
  if (Array.isArray(n.strokes)) n.strokes = (n.strokes as unknown[]).map(paint);
  if (Array.isArray(n.children)) n.children = (n.children as NodeInput[]).map((c) => recolorInput(c, color));
  return n as NodeInput;
}

/** An uploaded icon at `size` (longest side), optionally in one colour. */
export function customIconNode(icon: CustomIcon, opts: IconNodeOptions = {}): NodeInput {
  const k = Number(opts.size) > 0 ? Number(opts.size) / Math.max(icon.width, icon.height, 1) : 1;
  let node = scaleInput({ ...icon.node, x: 0, y: 0 } as NodeInput, k);
  if (opts.color) node = recolorInput(node, opts.color);
  return { ...node, name: opts.name ?? icon.name } as NodeInput;
}
